s=page(140,'c06','131','Methods of propaganda (14–17: fear and doubt, gifts, slogans, selected words)','پروپیگنڈہ کے طریقے (۱۴–۱۷)','د پروپېګنډا طریقې (۱۴–۱۷)','propm4')
F=Flow(s)
for h,he,hp,u,e,p in [
 ('۱۴۔ خوف، غیر یقینی صورتِ حال اور شک','14. Fear, an uncertain situation and doubt','۱۴. ویره، نا یقیني حالت او شک','لوگوں کا ان کے عقائد اور سوچ وغیرہ پر شک، خوف اور بے یقینی پیدا کرنا بھی پروپیگنڈے کا ایک اہم طریقہ ہے۔ ایسی افواہیں پھیلانا، سرگرمیاں کرنا، غلط معلومات پھیلانا کہ لوگوں کو ان کی سوچ، سرگرمیوں، گروہوں اور نظریے وغیرہ پر شک پیدا ہو اور ان کو بھیانک نتائج نظر آئیں۔ اس سے پروپیگنڈہ کرنے والا اپنے مقصد میں کامیاب ہو جاتا ہے۔','To create doubt, fear and uncertainty in people about their beliefs and thinking and so on is also an important method of propaganda. To spread such rumours, carry out activities, spread wrong information so that doubt arises in people about their thinking, activities, groups and ideology and so on and they see terrible consequences. By this the propagandist succeeds in his aim.','د خلکو په عقیدو او سوچ او نورو شک، ویره او ناباوري پیدا کول هم د پروپېګنډا یوه مهمه طریقه ده. داسې افواګانې خپرول، فعالیتونه کول، غلط معلومات خپرول چې خلکو ته د هغوی په فکر، فعالیتونو، ډلو او نظریې او نورو شک پیدا شي او هغوی ته ډارونکې پایلې ښکاره شي. له دې نه پروپېګنډا کوونکی خپلې موخې ته بریالی کېږي.'),
 ('۱۵۔ تحائف (Gifts)','15. Gifts','۱۵. ډالۍ (Gifts)','یہ بھی پروپیگنڈے کا ایک بارآور طریقہ ہے۔ ایک شخص دوسرے کو ایک چھوٹا سا تحفہ دیتا ہے۔ اس سے دونوں کے درمیان ایک جذباتی تعلق پیدا ہو جاتا ہے۔ جواب میں تحفہ لینے والا تحفہ دینے والے کے لیے بڑا کام کر دیتا ہے۔ مثال کے طور پر ایک سیلز مین ایک دکاندار کو ایک چھوٹا تحفہ دیتا ہے تو اس کے بدلے دکاندار سیلز مین سے بڑی خریداری کرتا ہے۔','This too is a fruitful method of propaganda. One person gives another a small gift. By this an emotional relationship arises between the two. In return the recipient does a big favour for the giver. For example, a salesman gives a shopkeeper a small gift and, in return, the shopkeeper makes a big purchase from the salesman.','دا هم د پروپېګنډا یوه ګټوره طریقه ده. یو کس بل ته یوه وړه ډالۍ ورکوي. له دې نه د دواړو ترمنځ یوه جذباتي اړیکه پیدا کېږي. په ځواب کې ډالۍ اخیستونکی د ډالۍ ورکوونکي لپاره لوی کار کوي. د بېلګې په توګه یو سیلزمین یو دوکاندار ته یوه وړه ډالۍ ورکوي نو په بدل کې دوکاندار له سیلزمین نه لوی پېر کوي.'),
 ('۱۶۔ نعرے (Slogans)','16. Slogans','۱۶. نارې (Slogans)','نعرے پروپیگنڈہ کا ایک اہم اور مسلمہ طریقہ ہیں۔ اس میں چند منتخب الفاظ کے جملے بنائے جاتے ہیں جس کا ایک خاص مقصد ہوتا ہے۔ ان کی بار بار تکرار کی جاتی ہے اور اس سے رائے عامہ کی تشکیل ہوتی ہے۔ مثال کے طور پر پہلی جنگِ عظیم کے بعد جرمنوں کا یہ نعرہ تھا کہ «مادرِ وطن کو دو حصوں میں تقسیم کر دیا گیا ہے۔» برازیل کے لوگوں کا نعرہ کہ «یہاں رہو یا چھوڑو»، عراق میں امریکہ کی سرگرمیوں کے خلاف امریکہ مخالف یہ نعرہ کہ «تیل کے لیے خون»، روس میں لینن کا یہ نعرہ کہ «دنیا بھر کے مزدور متحد ہو جاؤ» وغیرہ وغیرہ۔','Slogans are an important and accepted method of propaganda. In it sentences of a few selected words are made which have a particular purpose. They are repeated again and again and by this public opinion is formed. For example, after the First World War this was the slogan of the Germans: “The motherland has been divided in two.” The Brazilians’ slogan “Stay here or leave”; in Iraq the anti-American slogan against American activities “Blood for oil”; in Russia Lenin’s slogan “Workers of the world, unite”, and so on and so on.','نارې د پروپېګنډا یوه مهمه او منل شوې طریقه دي. په دې کې د څو غوره شویو ټکو جملې جوړېږي چې یوه ځانګړې موخه لري. هغوی بیا بیا تکرارېږي او له دې نه د عامې رایې جوړېدنه کېږي. د بېلګې په توګه د لومړۍ نړیوالې جګړې وروسته د جرمنانو دا نعره وه چې «مور وطن په دوو برخو ویشل شوی دی.» د برازیل خلکو نعره چې «دلته اوسېږئ یا پرېږدئ»، په عراق کې د امریکا د فعالیتونو پر ضد دا د امریکا ضد نعره چې «د تېلو لپاره وینه»، په روس کې د لینن دا نعره چې «د نړۍ مزدوران یو شئ» او داسې نور.'),
 ('۱۷۔ عمدہ اور نادر الفاظ (Selected Words)','17. Select and rare words','۱۷. غوره او نادر ټکي (Selected Words)','مخاطب لوگوں کے اقدار میں سے عمدہ الفاظ تلاش کر کے کسی فرد، نظریے، عمل یا سرگرمی وغیرہ کے حق میں استعمال کرنا۔ اس کے مخاطب لوگوں پر مثبت اثر پڑتا ہے۔ مثال کے طور پر امن، خوشحالی، تحفظ، ہوشیار قیادت، آزادی، سچائی اور ناموس وطن وغیرہ ایسے الفاظ ہیں جو پروپیگنڈہ کرنے والا استعمال کرتا ہے۔','To find fine words from among the values of the people addressed and use them in favour of some individual, ideology, action or activity and so on. This has a positive effect on the people addressed. For example, peace, prosperity, security, clever leadership, freedom, truth and the honour of the homeland and so on are such words that the propagandist uses.','د هغو خلکو له ارزښتونو نه غوره ټکي موندل او د کوم فرد، نظریې، عمل یا فعالیت او نورو په ګټه کارول. له دې نه پر مخاطب خلکو مثبت اغېز پرېوځي. د بېلګې په توګه امن، هوساینه، خوندیتوب، هوښیاره مشري، آزادي، رښتینولي او د وطن ناموس او نور داسې ټکي دي چې پروپېګنډا کوونکی یې کاروي.')]:
    H(s,h,he,hp); P(s,u,e,p)
F.done()
